    # That's 252 terms (5 to 256).
    
    # Let me just do a proper search.
    
    def dfs(target, min_d, max_terms, path):
        """Find representation of target as sum of at most max_terms unit fractions
        with denominators >= min_d. Returns list of denominators or None."""
        if time.time() > deadline:
            return None
        if max_terms == 0:
            return [] if target == 0 else None
        if target == 0:
            return []
        if target <= 0:
            return None
        
        # Lower bound: d >= max(min_d, floor(1/target) + 1)
        num, den = target.numerator, target.denominator
        if den == 0:
            return None
        lower = max(min_d, den // num + 1)
        
        # Upper bound: target <= 1/d + (max_terms-1)/(d+1)
        # For d large enough, this is always satisfied, so we iterate
        # But we need a reasonable upper bound to avoid infinite loop
        # target > 0, so 1/d < target => d > 1/target
        # Also target <= max_terms / d => d <= max_terms / target
        # For Fraction target = p/q: d <= max_terms * q / p
        upper = max_terms * den // num + 1
        upper = max(upper, lower)
        # Cap upper to avoid too large range
        if upper - lower > 100000:
            upper = lower + 100000
        
        for d in range(lower, upper + 1):
            if time.time() > deadline:
                return None
            if d < 5:
                continue
            term = Fraction(1, d)
            if term >= target:
                continue
            remainder = target - term
            if remainder <= 0:
                continue
            # Feasibility check
            if max_terms - 1 > 0:
                # remainder <= (max_terms-1) / (d+1)
                if remainder > (max_terms - 1) * Fraction(1, d + 1):
                    continue
            if max_terms - 1 == 0:
                if remainder == 0:
                    return [d]
                continue
            result = dfs(remainder, d + 1, max_terms - 1, path + [d])
            if result is not None:
                return [d] + result
        return None
    
    best = None
